<script>
  import DebugPanel from './DebugPanel.svelte';
  import TrackArtwork from './TrackArtwork.svelte';
  import Icon from './Icon.svelte';import ControlCenter from './ControlCenter.svelte';import Lights from './Lights.svelte';import Thermostat from './Thermostat.svelte';import ReminderList from './ReminderList.svelte';import AutoAction from './AutoAction.svelte';import Volume from './Volume.svelte';
  let {screen}=$props();let m=$derived(screen.model);let track=$derived(screen.tracks[m.song]);
  let remaining=$derived(m.timer?(m.timer.end?Math.max(0,(m.timer.end-m.now)/1000):m.timer.remaining):m.timerDraft);
</script>
{#if m.view==='control'}<ControlCenter {screen} />
{:else if m.view==='lights'}<Lights {screen} />
{:else if m.view==='climate'}<Thermostat {screen} />
{:else if m.view==='timer'}<div class="center-task"><div class="timer-adjust"><button class="circle-button" data-action="timer-minus" aria-label="Subtract one minute"><Icon name="minus" /></button><div class="big-time" data-timer-big>{screen.duration(remaining)}</div><button class="circle-button" data-action="timer-plus" aria-label="Add one minute"><Icon name="plus" /></button></div>{#if !m.timer}<div class="preset-row">{#each [60,300,600,900] as seconds (seconds)}<button data-timer-preset={seconds} aria-pressed={m.timerDraft===seconds}>{seconds/60} min</button>{/each}</div>{:else}<p class="subtle">{m.timer.end?'Running':'Paused'}</p>{/if}<div class="task-actions">{#if m.timer}<button class="button-primary" data-action="timer-pause">{m.timer.end?'Pause':'Resume'}</button><button class="button-secondary" data-action="timer-cancel">Cancel</button>{:else}<AutoAction label="Start timer" action="timer-save" active={!!m.auto} />{/if}</div><p class="auto-caption" data-auto-caption>{m.autoCaption||(!m.timer?'5 minutes':'')}</p></div>
{:else if m.view==='new-reminder'}<div class="center-task"><form class="reminder-form" data-form="reminder"><div class="field"><label for="reminder-v2">Remember to</label><input id="reminder-v2" name="text" data-input="reminder" maxlength="160" placeholder="Reminder" value={m.reminderDraft} autocomplete="off" /></div><div class="deadline-line"><label for="deadline-v2">When</label><input type="datetime-local" id="deadline-v2" name="deadline" data-input="deadline" value={m.reminderDeadline} aria-label="Reminder deadline" /></div><p class="subtle" style="margin-top:8px;font-size:11px">Optional</p><div class="task-actions"><AutoAction label="Save reminder" action="reminder-save" active={!!m.auto} /></div><p class="auto-caption" data-auto-caption>{m.autoCaption}</p></form></div>
{:else if m.view==='reminders'}<div class="reminders-layout"><div class="section-line"><span class="subtle">{m.reminders.filter(r=>!r.done).length} remaining · Swipe right to finish</span><button data-action="new-reminder" aria-label="Add reminder"><Icon name="plus" /></button></div><ReminderList {screen} /></div>
{:else if m.view==='contacts'}
  <div class="contacts" class:camera-contacts={m.haMode!=='demo'}>
    {#if m.haMode==='demo'}
      {#each [['Mom','M','Audio'],['Alex','A','Audio'],['Front door','video','Camera']] as [name,letter,label] (name)}<button class="contact-button" data-contact={name}><span class="avatar">{#if letter==='video'}<Icon name="video" />{:else}{letter}{/if}</span><span>{name}</span><small>{label}</small></button>{/each}
    {:else}
      {#each m.cameras as camera (camera.id)}
        <button class="contact-button" data-camera={camera.id} disabled={!camera.available}><span class="avatar"><Icon name="video" /></span><span>{camera.name}</span><small>{camera.available?'Live camera · Video only':'Unavailable'}</small></button>
      {:else}<p class="subtle" role="status">{m.haMode==='loading'?'Connecting to Home Assistant':m.haStatus==='connected'?'No cameras selected in Home Assistant configuration':m.haLabel}</p>{/each}
    {/if}
  </div>

{:else if m.view==='music'}<div class="music-layout"><TrackArtwork url={m.spotifyArtworkUrl} /><div class="music-info"><h2>{track[0]}</h2><p class="subtle">{track[1]}</p>{#if m.spotifyAlbum}<p class="subtle music-album" data-album-title title={m.spotifyAlbum}>Album · {m.spotifyAlbum}</p>{/if}{#if m.spotifyMode!=='demo'}<p class="provider-note" role="status">{m.spotifyPending?m.spotifyActionLabel:m.spotifySeeking?'Seeking…':m.mediaLoaded?m.spotifyLabel:''}{m.spotifyDevice?' · '+m.spotifyDevice:''}</p>{#if ['not_authorized','authentication'].includes(m.spotifyStatus)}<button class="button-secondary" onclick={screen.connectSpotify}>Connect Spotify</button>{/if}{/if}<div class="music-buttons"><button data-action="shuffle" disabled={!screen.canControlSpotify()} aria-label="Shuffle" aria-pressed={m.shuffle}><Icon name="shuffle" /></button><button data-action="previous" disabled={!screen.canControlSpotify()} aria-label="Previous track"><Icon name="skip-back" /></button><button class="play-control" data-action="playpause" disabled={!screen.canControlSpotify()} aria-label={m.playing?'Pause':'Play'}><Icon name={m.playing?'pause':'play'} /></button><button data-action="next" disabled={!screen.canControlSpotify()} aria-label="Next track"><Icon name="skip-forward" /></button><button data-action="repeat" disabled={!screen.canControlSpotify()} aria-label={`Repeat: ${m.repeat}`} aria-pressed={m.repeat!=='off'}><Icon name={m.repeat==='track'?'repeat-1':'repeat'} /></button></div><input class="seek-track" disabled={!screen.canControlSpotify()} type="range" min="0" max={track[2]} value={m.position} data-input="seek" aria-label="Playback position" /><div class="track-times"><span data-track-time>{screen.duration(m.position)}</span><span>{screen.duration(track[2])}</span></div><Volume {screen} className="music-volume" stop /></div></div>
{:else if m.view==='weather'}<div class="center-task"><div class="answer-weather"><Icon name="cloud-sun" /><strong>28°</strong></div><h2>Partly cloudy</h2><p class="subtle">High 30° · Low 25°</p></div>
{:else if m.view==='intent'}<div class="history-layout"><div class="history-list">{#each m.history as item,i (item.result.utteranceId)}<button data-history={i} aria-pressed={m.historyIndex===i}><strong>{item.result.intent}</strong><small>{new Date(item.timestamp).toLocaleTimeString()} · {item.source==='onnx-simulated'?'ONNX fixture':item.source?.startsWith('onnx-')?'CPU ONNX':'Touch'}</small></button>{:else}<p class="subtle">No requests yet.</p>{/each}</div><div class="history-detail"><pre>{JSON.stringify(m.history[m.historyIndex]??{input:'intent + parameters',asr:false,simulated:true},null,2)}</pre></div></div><p class="demo-note">Last 30 requests · {m.runtimeMode?`${m.runtimeEngine} · Actions ${m.runtimeActions?'enabled':'disabled'}`:'Synthetic inference'}</p>
{:else if m.view==='demo'}<DebugPanel {screen}/>
{/if}
